custom_qss:
/* ============================================================
   EMBER - dark glass theme (red)
   Pushes the series further:
   - visible glass: every fill is 14-36% red over a warm gradient
   - heat gradients on discrete surfaces only (tab, slider, progress)
   - ember crown: faint red hairline on top edge of window/dialogs
   - chrome melts; alpha hairlines; no boxes anywhere
   ============================================================ */

* {
    border: none;
    background-color: transparent !important;
    color: #f2dede !important;
}

/* --- melt rules first: everything defaults to glass-over-nothing --- */
QAbstractScrollArea, QFrame, QStackedWidget, QScrollArea, QTabWidget, QWidget {
    background: transparent !important;
    border: none;
}

/* --- the single big gradient zone + ember crown --- */
QMainWindow {
    background: qlineargradient(x1:0, y1:0, x2:0.12, y2:1,
        stop:0 #221111, stop:0.45 #130807, stop:1 #0a0404) !important;
    border-top: 1px solid rgba(252,165,165,60);
}
QDialog {
    background: qlineargradient(x1:0, y1:0, x2:0.12, y2:1,
        stop:0 #221111, stop:0.45 #130807, stop:1 #0a0404) !important;
    border-top: 1px solid rgba(252,165,165,60);
}

/* --- menubar melts --- */
QMenuBar {
    background: transparent !important;
}
QMenuBar::item {
    padding: 4px 10px;
    border-radius: 4px;
    background: transparent !important;
    color: #9a6f6f !important;
}
QMenuBar::item:selected {
    background: rgba(239,68,68,64) !important;
    color: #f2dede !important;
}

/* --- popup card --- */
QMenu {
    background: #170b0a !important;
    border: 1px solid rgba(252,165,165,48);
    border-radius: 7px;
    padding: 5px;
}
QMenu::item {
    padding: 5px 22px 5px 14px;
    border-radius: 5px;
    background: transparent !important;
    color: #f2dede !important;
}
QMenu::item:selected {
    background: rgba(239,68,68,92) !important;
    color: #fee2e2 !important;
}
QMenu::item:disabled {
    color: #563d3d !important;
}
QMenu::separator {
    height: 1px;
    background: rgba(252,165,165,48)S;
    margin: 5px 8px;
}

/* --- toolbars: pure chrome --- */
QToolBar {
    background: transparent !important;
    spacing: 2px;
    padding: 3px;
}
QToolBar::separator {
    background: rgba(252,165,165,48)S;
    width: 1px;
    margin: 5px 3px;
}
QToolBar QToolButton {
    background: transparent !important;
    padding: 4px 7px;
    border-radius: 5px;
    color: #9a6f6f !important;
}
QToolBar QToolButton:hover {
    background: rgba(239,68,68,64) !important;
    color: #f2dede !important;
}
QToolBar QToolButton:checked, QToolBar QToolButton:pressed {
    background: rgba(239,68,68,92) !important;
    border-bottom: 2px solid #ef4444;
    color: #fca5a5 !important;
}
QToolBar QToolButton:disabled {
    color: #563d3d !important;
}

QToolButton {
    background: transparent !important;
    padding: 4px 7px;
    border-radius: 5px;
    color: #9a6f6f !important;
}
QToolButton:hover {
    background: rgba(239,68,68,64) !important;
    color: #f2dede !important;
}
QToolButton:checked, QToolButton:pressed {
    background: rgba(239,68,68,92) !important;
    border-bottom: 2px solid #ef4444;
    color: #fca5a5 !important;
}
QToolButton:disabled {
    color: #563d3d !important;
}

/* --- buttons: red glass, underline accent --- */
QPushButton {
    background-color: rgba(239,68,68,36) !important;
    border-radius: 6px;
    padding: 5px 16px;
    color: #f2dede !important;
}
QPushButton:hover {
    background-color: rgba(239,68,68,64) !important;
    color: #fee2e2 !important;
}
QPushButton:pressed {
    background-color: rgba(239,68,68,92) !important;
}
QPushButton:checked {
    background-color: rgba(239,68,68,92) !important;
    border-bottom: 2px solid #ef4444;
    color: #fca5a5 !important;
}
QPushButton:default {
    border-bottom: 2px solid #ef4444;
}
QPushButton:disabled {
    color: #563d3d !important;
}

/* --- inputs: glass fill, red focus line --- */
QLineEdit, QSpinBox, QDoubleSpinBox, QTextEdit, QPlainTextEdit {
    background-color: rgba(239,68,68,36) !important;
    border-bottom: 2px solid rgba(252,165,165,48);
    border-radius: 5px 5px 0 0;
    padding: 4px 7px;
    color: #f2dede !important;
    selection-background-color: rgba(239,68,68,66);
    selection-color: #fee2e2;
}
QLineEdit:focus, QSpinBox:focus, QDoubleSpinBox:focus, QTextEdit:focus, QPlainTextEdit:focus {
    border-bottom: 2px solid #ef4444;
    background-color: rgba(239,68,68,64) !important;
}
QLineEdit:disabled, QSpinBox:disabled, QDoubleSpinBox:disabled,
QTextEdit:disabled, QPlainTextEdit:disabled {
    color: #563d3d !important;
}
QSpinBox::up-button, QSpinBox::down-button,
QDoubleSpinBox::up-button, QDoubleSpinBox::down-button {
    background: transparent !important;
    border: none;
    width: 16px;
}

QComboBox {
    background-color: rgba(239,68,68,36) !important;
    border-bottom: 2px solid rgba(252,165,165,48);
    border-radius: 5px 5px 0 0;
    padding: 4px 7px;
    color: #f2dede !important;
}
QComboBox:hover {
    border-bottom: 2px solid rgba(239,68,68,150);
}
QComboBox:focus {
    border-bottom: 2px solid #ef4444;
}
QComboBox::drop-down {
    border: none;
    background: transparent !important;
    width: 18px;
}
QComboBox QAbstractItemView {
    background: #170b0a !important;
    border: 1px solid rgba(252,165,165,48);
    border-radius: 6px;
    padding: 4px;
    selection-background-color: rgba(239,68,68,66);
}
QComboBox:disabled {
    color: #563d3d !important;
}

/* --- checkboxes: solid red chips when checked --- */
QCheckBox, QRadioButton {
    color: #f2dede !important;
    background: transparent !important;
    padding: 2px;
}
QCheckBox::indicator, QRadioButton::indicator {
    width: 15px;
    height: 15px;
    background: rgba(239,68,68,64) !important;
    border-radius: 4px;
}
QRadioButton::indicator {
    border-radius: 8px;
}
QCheckBox::indicator:hover, QRadioButton::indicator:hover {
    background: rgba(239,68,68,92) !important;
}
QCheckBox::indicator:checked, QRadioButton::indicator:checked {
    background: #ef4444 !important;
}
QCheckBox::indicator:checked:hover, QRadioButton::indicator:checked:hover {
    background: #f87171 !important;
}
QCheckBox:disabled, QRadioButton:disabled {
    color: #563d3d !important;
}

/* --- tabs: selected = heat-gradient glass pill + red underline --- */
QTabBar {
    background: transparent !important;
}
QTabBar::tab {
    background: transparent !important;
    color: #9a6f6f !important;
    padding: 6px 16px;
    border-radius: 5px 5px 0 0;
    margin: 0 1px;
}
QTabBar::tab:hover {
    color: #f2dede !important;
    background: rgba(239,68,68,36) !important;
}
QTabBar::tab:selected {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
        stop:0 rgba(239,68,68,80), stop:1 rgba(239,68,68,36)) !important;
    color: #fca5a5 !important;
    border-bottom: 2px solid #ef4444;
}
QTabBar::tab:disabled {
    color: #563d3d !important;
}
QTabBar::close-button {
    background: transparent !important;
    border: none;
    border-radius: 3px;
}
QTabBar::close-button:hover {
    background: rgba(239,68,68,92) !important;
}
QTabWidget::pane {
    border: none;
    border-top: 1px solid rgba(252,165,165,48)S;
    background: transparent !important;
}

/* --- docks: melted, red tick + bright title --- */
QDockWidget {
    background: transparent !important;
    border: none;
}
QDockWidget::title {
    background: transparent !important;
    border: none;
    border-bottom: 1px solid rgba(252,165,165,48)S;
    border-left: 3px solid #ef4444;
    padding: 6px 9px;
    color: #fca5a5 !important;
    font-weight: 600;
}
QDockWidget::close-button, QDockWidget::float-button {
    background: transparent !important;
    border: none;
    padding: 2px;
    border-radius: 3px;
}
QDockWidget::close-button:hover, QDockWidget::float-button:hover {
    background: rgba(239,68,68,64) !important;
}

/* --- group boxes: title alone groups, in bright red --- */
QGroupBox {
    background: transparent !important;
    border: none;
    margin-top: 14px;
    padding-top: 4px;
    font-weight: 600;
    color: #f2dede !important;
}
QGroupBox::title {
    subcontrol-origin: margin;
    subcontrol-position: top left;
    padding: 0 6px;
    background: transparent !important;
    color: #fca5a5 !important;
}

/* --- item views: red glass lists --- */
QAbstractItemView {
    background: rgba(239,68,68,36) !important;
    border: none;
    border-radius: 6px;
    alternate-background-color: rgba(239,68,68,14);
    selection-background-color: rgba(239,68,68,42);
    selection-color: #f2dede;
    outline: none;
}
QAbstractItemView::item {
    padding: 3px;
}
QAbstractItemView::item:hover {
    background: rgba(239,68,68,64) !important;
}
QAbstractItemView::item:selected {
    background: rgba(239,68,68,42) !important;
    border-left: 3px solid #ef4444;
    color: #fee2e2 !important;
}
QAbstractItemView::item:selected:!active {
    background: rgba(239,68,68,28) !important;
    border-left: 3px solid rgba(239,68,68,120);
}
QTreeView::item, QTreeWidget::item, QTreeWidgetItem,
QTableView::item, QListView::item, QListWidget::item {
    background: transparent !important;
}

QHeaderView {
    background: transparent !important;
    border: none;
}
QHeaderView::section {
    background: transparent !important;
    border: none;
    border-bottom: 1px solid rgba(252,165,165,48)S;
    padding: 5px 7px;
    color: #9a6f6f !important;
    font-weight: 600;
}
QHeaderView::section:hover {
    color: #f2dede !important;
}

/* --- scrollbars: sleeping until touched, then full red --- */
QScrollBar:vertical {
    background: transparent !important;
    width: 10px;
    margin: 2px;
}
QScrollBar::handle:vertical {
    background: rgba(239,68,68,70);
    border-radius: 4px;
    min-height: 28px;
}
QScrollBar::handle:vertical:hover {
    background: rgba(239,68,68,190);
}
QScrollBar::handle:vertical:pressed {
    background: #ef4444;
}
QScrollBar::add-line:vertical, QScrollBar::sub-line:vertical {
    height: 0;
    background: none;
    border: none;
}
QScrollBar::add-page:vertical, QScrollBar::sub-page:vertical {
    background: transparent !important;
}
QScrollBar:horizontal {
    background: transparent !important;
    height: 10px;
    margin: 2px;
}
QScrollBar::handle:horizontal {
    background: rgba(239,68,68,70);
    border-radius: 4px;
    min-width: 28px;
}
QScrollBar::handle:horizontal:hover {
    background: rgba(239,68,68,190);
}
QScrollBar::handle:horizontal:pressed {
    background: #ef4444;
}
QScrollBar::add-line:horizontal, QScrollBar::sub-line:horizontal {
    width: 0;
    background: none;
    border: none;
}
QScrollBar::add-page:horizontal, QScrollBar::sub-page:horizontal {
    background: transparent !important;
}
QScrollBar::corner {
    background: transparent !important;
}

/* --- sliders: heat gradient fill, warm white knob --- */
QSlider::groove:horizontal {
    background: rgba(252,165,165,40) !important;
    height: 3px;
    border-radius: 2px;
}
QSlider::sub-page:horizontal {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:0,
        stop:0 #7f1d1d, stop:1 #ef4444) !important;
    border-radius: 2px;
}
QSlider::add-page:horizontal {
    background: rgba(252,165,165,40) !important;
    border-radius: 2px;
}
QSlider::handle:horizontal {
    background: #fee2e2 !important;
    width: 11px;
    margin: -5px 0;
    border-radius: 6px;
}
QSlider::handle:horizontal:hover {
    background: #fca5a5 !important;
}
QSlider::groove:vertical {
    background: rgba(252,165,165,40) !important;
    width: 3px;
    border-radius: 2px;
}
QSlider::sub-page:vertical {
    background: qlineargradient(x1:0, y1:1, x2:0, y2:0,
        stop:0 #7f1d1d, stop:1 #ef4444) !important;
    border-radius: 2px;
}
QSlider::add-page:vertical {
    background: rgba(252,165,165,40) !important;
    border-radius: 2px;
}
QSlider::handle:vertical {
    background: #fee2e2 !important;
    height: 11px;
    margin: 0 -5px;
    border-radius: 6px;
}
QSlider::handle:vertical:hover {
    background: #fca5a5 !important;
}

/* --- progress: three-stop heat shine --- */
QProgressBar {
    background: rgba(239,68,68,36) !important;
    border-radius: 5px;
    text-align: center;
    color: #f2dede !important;
    min-height: 14px;
}
QProgressBar::chunk {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:0,
        stop:0 #7f1d1d, stop:0.6 #ef4444, stop:1 #fca5a5) !important;
    border-radius: 5px;
}

/* --- statusbar melts --- */
QStatusBar {
    background: transparent !important;
    border: none;
    border-top: 1px solid rgba(252,165,165,48)S;
    color: #9a6f6f !important;
}
QStatusBar::item {
    background: transparent !important;
}

/* --- tooltip: ember card --- */
QToolTip {
    background: #1a0d0b !important;
    border: 1px solid rgba(239,68,68,130);
    border-radius: 6px;
    padding: 5px 8px;
    color: #f2dede !important;
}

/* --- splitters: invisible until hovered --- */
QSplitter {
    background: transparent !important;
    border: none;
}
QSplitter::handle {
    background: transparent !important;
}
QSplitter::handle:hover {
    background: rgba(239,68,68,64) !important;
}
